from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    def is_balanced(group: str) -> bool:
        stack = []
        for char in group:
            if char == '(':
                stack.append(char)
            elif char == ')':
                if not stack or stack[-1] != '(':
                    return False
                stack.pop()
        return not stack

    def separate_groups(paren_string: str) -> List[str]:
        groups = []
        group = ''
        for char in paren_string:
            if char == '(':
                if group:
                    groups.append(group)
                group = '('
            elif char == ')':
                group += ')'
                groups.append(group)
                group = ''
        if group:
            groups.append(group)
        return groups

    def remove_spaces(paren_string: str) -> str:
        return ''.join(char for char in paren_string if char != ' ')

    paren_string = remove_spaces(paren_string)
    groups = separate_groups(paren_string)
    result = [group for group in groups if is_balanced(group)]

    return result

